examples.code:
import requests

new_post = {"title": "Hello", "body": "My first post"}
response = requests.post("https://api.example.com/posts", json=new_post)

if response.status_code == 201:
    created = response.json()
    print(f"Created post with id {created['id']}")
elif 400 <= response.status_code < 500:
    print(f"Request was rejected ({response.status_code}): {response.json().get('error')}")
else:
    print(f"Unexpected server response: {response.status_code}")

